css:
.sb-annual .sb-konto {
	table-layout: fixed;
}

.sb-annual .sb-konto > tbody > tr > td.sb-side {
	padding: 0 2mm 0 0;
	vertical-align: top;
	width: 50%;
}

.sb-annual h3 {
	font-size: 9.5pt;
	font-weight: 600;
	margin: 3mm 0 1mm;
}

.sb-annual .sb-side h3 {
	margin-top: 0;
}

.sb-annual .sb-position {
	text-align: left;
}

.sb-annual .sb-wide {
	font-size: 7pt;
	table-layout: auto;
}

.sb-annual .sb-wide .sb-num {
	width: auto;
}

.sb-annual .sb-group-head td {
	font-weight: 600;
	padding-top: 1.8mm;
}
